const body = $input.first().json.body || {};
const action = body.action || 'updated';
const column = (body.projects_v2_item?.column_name || body.column_name || body.issue?.state || 'In Progress').trim();
const issueNumber = body.issue?.number || body.projects_v2_item?.content_number || 1;
const issueTitle = body.issue?.title || body.projects_v2_item?.content_title || `Issue #${issueNumber}`;
const issueBody = body.issue?.body || body.projects_v2_item?.content_body || 'Automated task execution';
const branchName = `issue-${issueNumber}`;

return [{
  json: {
    action,
    column,
    issueNumber,
    issueTitle,
    issueBody,
    branchName,
    taskPrompt: `Issue #${issueNumber} [${issueTitle}]: ${issueBody}`
  }
}];
